--
-- Table structure for table `emd_guarantees`
--

DROP TABLE IF EXISTS `emd_guarantees`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `emd_guarantees` (
  `id` int NOT NULL AUTO_INCREMENT,
  `bg_for` varchar(200) DEFAULT NULL,
  `datefrom` date DEFAULT NULL,
  `bankguaranteeno` text,
  `favour_of` text,
  `po_no` text,
  `amount` decimal(12,2) DEFAULT NULL,
  `validupto` date DEFAULT NULL,
  `extenstionupto` date DEFAULT NULL,
  `lastdate` date DEFAULT NULL,
  `relese_date` date DEFAULT NULL,
  `po_or_rma` enum('PO','RM') DEFAULT NULL,
  `contect_per` varchar(100) DEFAULT NULL,
  `created` datetime DEFAULT NULL,
  `updated` datetime DEFAULT NULL,
  `board_name` varchar(255) DEFAULT NULL,
  `currency_type` varchar(45) DEFAULT 'INR',
  `claim_upto` date DEFAULT NULL,
  `status` enum('Y','N') DEFAULT 'N',
  `invoice_file` text,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=275 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

