DROP TABLE IF EXISTS `grn_inspection_details`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `grn_inspection_details` (
  `id` int NOT NULL AUTO_INCREMENT,
  `purchaseorder_id` varchar(55) DEFAULT NULL COMMENT 'purchase order primary key',
  `inspection_id` varchar(55) DEFAULT NULL COMMENT 'goods received primary id',
  `item_id` int DEFAULT NULL,
  `created` datetime DEFAULT CURRENT_TIMESTAMP,
  `issue_date` datetime DEFAULT NULL,
  `delivery_date` datetime DEFAULT NULL,
  `quantity` float DEFAULT NULL,
  `rate` double(10,2) DEFAULT NULL,
  `cost_price` double(10,2) DEFAULT NULL,
  `tax_id` int DEFAULT NULL,
  `tax` double(10,2) DEFAULT '0.00',
  `amount` double(10,2) DEFAULT NULL,
  `added_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `type` varchar(255) DEFAULT NULL,
  `store_id` int DEFAULT NULL,
  `status` enum('Y','N','R') DEFAULT 'Y' COMMENT 'R for check PO is revised or not',
  `vendor_id` int DEFAULT NULL,
  `delivery_schedule_id` int DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=663 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
