INSERT INTO `report_template` VALUES (1,'left','<table width=\"100%\" align=\"left\">\r\n  <tbody><tr>\r\n    <td style=\"text-align:left\" width=\"50%\"><img src=\"images/{logo}\" alt=\"\" border=\"0\" style=\"display:block;\" width=\"130px\" height=\"60px;\"><br><span style=\"display:block; color:#000; font-size:8px;font-weight:bold;\"><u>{subtitle2} ({subtitle1})</u></span> <br></td>\r\n    <td style=\"text-align:rigth;\" width=\"50%\" align=\"right\"><br>\r\n      <br>{address1}\r\n      <br>\r\n      {address2}<br>\r\n      Phone : &nbsp;{phone}&nbsp;&nbsp;Fax :{fax}<br>\r\n      Email : &nbsp;<u>{email},</u> <br>\r\n      Website : &nbsp;{website}<br></td>\r\n  </tr>\r\n\r\n</tbody></table>','N','General,Receipt'),(2,'right','<table width=\"100%\" align=\"left\">\r\n  <tbody><tr>\r\n    <td style=\"text-align:left;\" width=\"50%\" align=\"left\"><br>\r\n      <br>{address1}\r\n      <br>\r\n      {address2}<br>\r\n      Phone :  {phone}    \r\n      Fax :  {fax}<br>\r\n      Email :  <u>{email},</u> <br>\r\n      Website :  {website}<br></td>\r\n    <td style=\"text-align:right\" width=\"50%\"><img src=\"images/{logo}\" alt=\"\" border=\"0\" style=\"display:block;\" width=\"130px\" height=\"60px;\"><br>\r\n      <span style=\"display:block; color:#000; font-size:8px;\"><u>{subtitle1}</u><br><u>{subtitle2}</u></span> <br></td>\r\n  </tr>\r\n</tbody></table>','N','General,Receipt'),(3,'center','<table width=\"100%\" align=\"left\" cellspacing=\"0\">\r\n  <tbody><tr>\r\n    <td style=\"text-align:center\" width=\"100%\"><img src=\"images/{logo}\" alt=\"\" border=\"0\" style=\"display:block;\" width=\"150px\" height=\"70px;\"><br>\r\n      <span style=\"display:block; color:#000; font-size:8px;\"><u>{subtitle1}</u><br><u>{subtitle2}</u></span></td>\r\n  </tr>\r\n  <tr>\r\n<td width=\"60%\"><span style=\"text-align:left; display:inline-block; font-size:11px;\"> {address1},{address2}</span></td>\r\n\r\n<td align=\"right\" width=\"40%\" style=\"font-size:11px;\"><span style=\"text-align:left; display:inline-block; font-size:11px;\">Phone : &nbsp;{phone} </span> &nbsp;  &nbsp; </td>\r\n   \r\n  </tr>\r\n</tbody></table>','N','General,Receipt'),(4,'equal','<table width=\"100%\" align=\"center\">\r\n<tbody><tr>\r\n<td width=\"33.3333%\"></td>\r\n<td width=\"33.3333%\" align=\"center\">Sri Sai Shikshan Sansthan</td>\r\n<td width=\"33.3333%\" align=\"right\">\r\n<table width=\"100%\" cellpadding=\"2px\">\r\n<tbody><tr>\r\n<td width=\"50%\"></td>\r\n<td width=\"50%\" style=\"border:1px solid #000;\" align=\"center\">\r\n<a href=\"javascript:void(0);\" style=\"text-decoration:none; color:#000; width:100px; display:inline-block; border-top:1px solid #000;  border-left:1px solid #000;  border-right:1px solid #000;  border-bottom:1px solid #000;\"><strong> {mode} </strong></a></td>\r\n	</tr>\r\n</tbody></table></td>\r\n</tr>\r\n<tr>\r\n    <td style=\"text-align:center\" width=\"100%\"><img src=\"images/{logo}\" alt=\"\" border=\"0\" style=\"display:block;width: 150px; height:70px;\"><br>\r\n      <span style=\"display:block; color:#000;\">{subtitle1}<br>{subtitle2}</span> <br></td>\r\n  </tr>\r\n  <tr>\r\n    <td style=\"text-align:left; display:inline-block; font-size:11px;\" width=\"60%\" align=\"left\">{address1}<br>{address2}\r\n     </td>\r\n    <td style=\"text-align:right; display:inline-block; font-size:11px;\" width=\"40%\" align=\"right\"> Phone : {phone}</td>\r\n  </tr>\r\n</tbody></table>','Y','general,receipt'),(7,'Vertical Student Id Card','<head>\n    <link href=\"https://fonts.googleapis.com/css2?family=Open+Sans:wght@600;800&display=swap\" rel=\"stylesheet\">\n    <style>\n        .cardHolder {\n            background: #fff;\n            height: 875px;\n            width: 550px;\n            border: 1px solid #ccc;\n            font-family: \'Open Sans\', sans-serif !important;\n            display: flex;\n            flex-direction: column;\n            align-items: center;\n            position: relative;\n            text-transform: uppercase !important;\n            box-sizing: border-box !important;\n        }\n        \n        .cardHeader {\n            /* display: flex; */\n            padding: 10px;\n            text-align: center;\n            padding-bottom: 0px;\n            position: relative;\n            z-index: 9;\n            padding-top: 15px;\n            box-sizing: border-box;\n        }\n        \n        .cardHeader .logo {\n            /* width: 80%; */\n            margin: auto;\n        }\n        /* .cardHeader .logo img {\n            width: 100%;\n            display: block;\n        } */\n        \n        .cardHeader .schoolDetail {\n            flex: 1;\n        }\n        \n        .cardHeader .schoolDetail h1 {\n            font-size: 40px;\n            font-weight: 800;\n            margin: 0px;\n            margin-bottom: 2px;\n            text-transform: uppercase;\n            color: #b82329;\n        }\n        \n        .cardHeader .schoolDetail p {\n            font-size: 19px;\n            font-weight: 600;\n            color: #000;\n            text-transform: capitalize;\n            margin: 0px;\n            line-height: 1.3;\n            letter-spacing: -.4px;\n        }\n        \n        .cardHeader .schoolDetail p.contact_no {\n            margin-top: 5px;\n            font-size: 18px;\n            font-weight: 700;\n        }\n        \n        .cardHeader .schoolDetail p b {\n            font-size: 24px;\n            font-weight: 800 !important;\n        }\n        \n        .imageHolder {\n            height: 190px;\n            width: 190px;\n            border: 1px solid #999;\n            margin: 5px auto;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            overflow: hidden;\n        }\n        \n        .imageHolder img {\n            width: 100%;\n            height: 100% !important;\n            border: none !important;\n        }\n        \n        .cardBody {\n            flex: 1;\n            padding: 0px 15px;\n            width: 100%;\n            text-align: center;\n            box-sizing: border-box;\n            position: relative;\n            z-index: 9;\n        }\n        \n        .cardBody h2 {\n            font-size: 28px;\n            color: #000;\n            text-align: center;\n            margin: 0px;\n            font-weight: 800;\n        }\n\n        .schoolDetail p {\n           width: 377px;\n        }\n        \n        .cardBody h2::before {\n            display: none;\n        }\n        \n        .cardBody h2::after {\n            display: none;\n        }\n        \n        .cardBody ul {\n            width: 100%;\n            margin: 0px;\n            margin-top: 10px;\n            padding: 0px 15px;\n            box-sizing: border-box;\n        }\n        \n        .cardBody ul li {\n            display: flex;\n            font-size: 17px;\n            text-align: left;\n            text-transform: capitalize;\n            list-style: none;\n            line-height: 32px;\n            font-weight: 600 !important;\n        }\n        \n        .cardBody ul li span:nth-child(1) {\n            flex: 1;\n        }\n        \n        .cardBody ul li span:nth-child(2) {\n            padding-right: 15px;\n        }\n        \n        .cardBody ul li span:nth-child(3) {\n            flex: 2.5;\n        }\n        \n        .cardFooter {\n            background: #eb258e;\n            width: 100%;\n            padding: 5px;\n            box-sizing: border-box;\n            position: relative;\n            position: relative;\n            z-index: 9;\n        }\n        \n        .cardFooter p {\n            margin: 0px;\n            text-align: center;\n            text-transform: capitalize;\n            color: #fff;\n            font-size: 14px;\n            padding: 0px 15px 15px;\n            font-weight: 600;\n        }\n        \n        .cardFooter p.office {\n            font-size: 16px;\n            padding: 2px 0px 6px;\n        }\n        \n        .cardFooter .signature {\n            position: absolute;\n            bottom: 67px;\n            left: 14px;\n        }\n        \n        .cardFooter .signature p {\n            color: #ec268f;\n            font-size: 20px;\n            text-transform: capitalize;\n            font-weight: 700;\n            text-align: left;\n            margin-bottom: 20px;\n        }\n        \n        .bgImage {\n            position: absolute;\n            left: 0px;\n            width: 100%;\n        }\n        \n        .signature img {\n            width: 150px !important;\n            padding-left: 15px;\n        }\n    </style>\n</head>\n\n<body>\n    <div id=\"html-content-holder{cnt}\">\n        <div class=\"cardHolder\">\n            <img src=\"https://www.idsprime.com/canvas_shivnagar_image/student/backgroung.png\" class=\"bgImage\" />\n            <div class=\"cardHeader\">\n                <div class=\"logo\">\n                    <img src=\"https://www.idsprime.com/canvas_shivnagar_image/student/canvaslogo.png\" alt=\"logo\" />\n\n                </div>\n                <div class=\"schoolDetail\">\n                    <p>92,Shiv Nagar, Harnathpura,Niwaru Road,Jaipur</p>\n                    <p class=\"contact_no\">Ph. : 7300052961</p>\n\n                </div>\n\n            </div>\n            <div class=\"cardBody\">\n\n                <div class=\"imageHolder\">\n                    {stu_image}\n                </div>\n                <h2>{firstname} {middlename} {lname}</h2>\n                <ul>\n                    <li class=\"listItem\">\n                        <span>DOB</span>\n                        <span>:</span>\n                        <span>{dob}</span>\n                    </li>\n                    <li class=\"listItem\">\n                        <span>Father\'s Name</span>\n                        <span>:</span>\n                        <span>{fathername}</span>\n                    </li>\n                    <li class=\"listItem\">\n                        <span>Contact No.</span>\n                        <span>:</span>\n                        <span>{sms_mobile}</span>\n                    </li>\n                    <li class=\"listItem\">\n                        <span>Mother\'s Name</span>\n                        <span>:</span>\n                        <span>{mothername}</span>\n                    </li>\n                    <li class=\"listItem\">\n                        <span>Address</span>\n                        <span>:</span>\n                        <span>{stu_address}</span>\n                    </li>\n\n                </ul>\n            </div>\n            <div class=\"cardFooter\">\n                <div class=\"signature\">\n                    <!-- {sign_url} -->\n                    <img src=\"https://www.idsprime.com/canvas_shivnagar_image/student/Director-Signature.jpg\" alt=\"\">\n                    <p>Director Signature</p>\n                </div>\n                <p class=\"office\">CANVAS HEAD OFFICE</p>\n                <p>A-47, A Pooja Path. Parshavanath Colony, Nirman Nagar. Jaipur-302019 Contact No.-7300052961</p>\n\n            </div>\n        </div>\n    </div>','N','Id Card'),(8,'Landscape Student ID','<link href=\"https://fonts.googleapis.com/css?family=Poppins:300,400,500,600,700&amp;display=swap\" rel=\"stylesheet\">\r\n<link href=\"css/titlefont.css\" rel=\"stylesheet\" type=\"text/css\">\r\n\r\n<style>\r\n* {\r\n	padding:0px;\r\n	margin:0px;\r\n}\r\nbody {\r\n	font-family: \'Poppins\';\r\n	background:#f2f1f1;\r\n	line-height:1.2\r\n}\r\nimg {\r\n	max-width:100%;\r\n}\r\nul {\r\n	list-style:none;\r\n}\r\nul li {\r\n	font-size:12px;\r\n	margin-bottom:2px\r\n}\r\n.stu_image{\r\nwidth:154px;\r\ndisplay:block;\r\n}\r\n</style>\r\n\r\n\r\n<div style=\"width:512px; margin:auto; height:322px; border-radius:10px; background:url(https://i.ibb.co/56gpZGB/id-card-bg.png) no-repeat center center; padding:10px 15px; display:flex; flex-direction:column; justify-content:space-between; position:relative\">\r\n  <div style=\"display:flex\">\r\n    <div style=\"margin-right:10px;\"><img src=\"{logo}\" style=\"display:block; width:175px\"></div>\r\n    <div>\r\n      <h1 style=\"padding:0px; margin:0px; font-family: \'OnStage\'; letter-spacing: 4px; color:#333;\">{school_name}</h1>\r\n      <p style=\"padding:0px; margin:0px; \">{address1}{address2}</p>\r\n    </div>\r\n  </div>\r\n  <div style=\" display:flex; margin-top:7px; flex:1;\">\r\n    <div style=\"margin-right:10px;\" class=\"stu_image\">{stu_image} </div>\r\n    <div style=\"width:100%;\">\r\n      <ul style=\"\">\r\n        <li style=\"margin-bottom:5px; font-family: \'Poppins\', ;\"> <b>{firstname} {middlename} {lname}</b> </li>\r\n        <li>\r\n          <ul style=\"display:flex;\">\r\n            <li style=\"width:100px\">S.R No.</li>\r\n            <li>:</li>\r\n            <li style=\"padding-left:20px;\">{enroll}</li>\r\n          </ul>\r\n        </li>\r\n        <li>\r\n          <ul style=\"display:flex;\">\r\n            <li style=\"width:100px\">F. Name</li>\r\n            <li>:</li>\r\n            <li style=\"padding-left:20px;\">{fathername}</li>\r\n          </ul>\r\n        </li>\r\n        <li>\r\n          <ul style=\"display:flex;\">\r\n            <li style=\"width:100px;\">M.Name</li>\r\n            <li>:</li>\r\n            <li style=\"padding-left:20px;\">{mothername}</li>\r\n          </ul>\r\n        </li>\r\n        <li>\r\n          <ul style=\"display:flex;\">\r\n            <li style=\"width:100px;\">D.O.B</li>\r\n            <li>:</li>\r\n            <li style=\"padding-left:20px;\">{dob}</li>\r\n          </ul>\r\n        </li>\r\n        <li>\r\n          <ul style=\"display:flex;\">\r\n            <li style=\"width:100px;\">Class</li>\r\n            <li>:</li>\r\n            <li style=\"padding-left:20px;\">{classtitle}<sup>th</sup> - Section-{section123}</li>\r\n          </ul>\r\n        </li>\r\n        <li>\r\n          <ul style=\"display:flex;\">\r\n            <li style=\"width:100px;\">Phone No.</li>\r\n            <li>:</li>\r\n            <li style=\"padding-left:20px;\">{sms_mobile}</li>\r\n          </ul>\r\n        </li>\r\n        <li>\r\n          <ul style=\"display:flex;\">\r\n            <li style=\"min-width:100px;\">Address</li>\r\n            <li>:</li>\r\n            <li style=\"padding-left:20px;\">{stu_address}</li>\r\n          </ul>\r\n        </li>\r\n      </ul>\r\n    </div>\r\n  </div>\r\n  <div style=\" display:flex; align-items:flex-end; position: absolute; bottom: 0px; width: 100%; bottom:10px\">\r\n    <div>{sign_url}</div>\r\n    <div style=\" background: #fff; font-size: 25px; color: #dcdcdc; margin: 0px 20px; padding: 5px; font-weight: 600;\">{academic year}</div>\r\n    <p style=\"font-size:16px; padding:5px;\">{phone}</p>\r\n  </div>\r\n</div>\r\n\r\n\r\n','N','Id Card'),(9,'Employee Landscape Id ','<link href=\"https://fonts.googleapis.com/css?family=Poppins:300,400,500,600,700&amp;display=swap\" rel=\"stylesheet\">\r\n<link href=\"css/titlefont.css\" rel=\"stylesheet\" type=\"text/css\">\r\n<style>\r\n* {\r\n	padding:0px;\r\n	margin:0px;\r\n}\r\nbody {\r\n	font-family: \'Poppins\';\r\n	background:#f2f1f1;\r\n	line-height:1.2\r\n}\r\nimg {\r\n	max-width:100%;\r\n}\r\nul {\r\n	list-style:none;\r\n}\r\nul li {\r\n	font-size:13px;\r\n	margin-bottom:3px\r\n}\r\n.hex {\r\n	display: inline-block;\r\n	position: relative;\r\n	width: 180px;\r\n	height: 151px;\r\n	background: #0092ca;\r\n	background: -moz-linear-gradient(60deg, #0092ca 50%, #2caae2 50%);\r\n	background: -webkit-linear-gradient(60deg, #0092ca 50%, #2caae2 50%);\r\n	background: linear-gradient(60deg, #0092ca 50%, #2caae2 50%);\r\nfilter: progid:DXImageTransform.Microsoft.gradient( startColorstr=\'#0092ca\', endColorstr=\'#2caae2\', GradientType=1 );\r\n	box-sizing: border-box;\r\n	-webkit-clip-path: polygon(0% 50%, 25% 0%, 75% 0%, 100% 50%, 75% 100%, 25% 100%);\r\n	-moz-clip-path: polygon(0% 50%, 25% 0%, 75% 0%, 100% 50%, 75% 100%, 25% 100%);\r\n	transform: rotate(90deg);\r\n	margin: auto;\r\n	-moz-transform: rotate(-150deg) translate(38px, 40px);\r\n	-webkit-transform: rotate(-150deg) translate(38px, 40px);\r\n	-o-transform: rotate(-150deg) translate(38px, 40px);\r\n	-ms-transform: rotate(-150deg) translate(38px, 40px);\r\n	transform: rotate(-150deg) translate(38px, 40px);\r\n}\r\n.hex-background {\r\n	position: absolute;\r\n	background-color: #fff;\r\n	top: 10px;\r\n	left: 10px;\r\n	width: 160px;\r\n	height: 131px;\r\n	-webkit-clip-path: polygon(0% 50%, 25% 0%, 75% 0%, 100% 50%, 75% 100%, 25% 100%);\r\n	-moz-clip-path: polygon(0% 50%, 25% 0%, 75% 0%, 100% 50%, 75% 100%, 25% 100%);/* margin: auto; */\r\n}\r\n\r\n.hex img {\r\n	position: absolute;\r\n	width: 160px;\r\n	height: 131px;\r\n	-webkit-clip-path: polygon(0% 50%, 25% 0%, 75% 0%, 100% 50%, 75% 100%, 25% 100%);\r\n	-moz-clip-path: polygon(0% 50%, 25% 0%, 75% 0%, 100% 50%, 75% 100%, 25% 100%);\r\n}\r\n.hex-background img{\r\ntransform: rotate(150deg);  margin: -10px;\r\n}\r\n</style>\r\n\r\n\r\n<div style=\"background:#f2f1f1;width:512px;\">\r\n<div style=\"width:512px; margin:auto; height:322px; border-radius:10px; background:url(../images/tacher_horizontal.jpg) no-repeat center center; padding:10px 15px; display:flex; flex-direction:column; justify-content:space-between; background-size: cover; position:relative;\">\r\n  <div style=\"display:flex\">\r\n    <div style=\"margin-right:10px;\"><img src=\"{logo}\" style=\"display:block; width:175px\"></div>\r\n    <div>\r\n      <h1 style=\"padding:0px; margin:0px; font-family: \'OnStage\'; letter-spacing: 4px; color:#333;\">{school_name}</h1>\r\n      <p style=\"padding:0px; margin:0px; \">{address1}{address2}</p>\r\n    </div>\r\n  </div>\r\n  <div>\r\n    <div class=\"hex\">\r\n      <div class=\"hex-background\">{emp_image}</div>\r\n    </div>\r\n    <div style=\" position:absolute; left:210px; top:105px; \">\r\n      <ul>\r\n        <li style=\"font-size:22px; font-weight:600;\">{firstname} {middlename} {lname}</li>\r\n        <li style=\"font-size:16px; font-weight:500;\">{designation}</li>\r\n        <li style=\"font-size:14px; font-weight:500; margin-top:20px;\">\r\n          <ul style=\"display:flex; flex-direction:column; align-items:center;\">\r\n            <li>\r\n              <ul style=\"display:flex;\">\r\n                <li style=\"width:100px\">Employee Id</li>\r\n                <li>:</li>\r\n                <li style=\"padding-left:20px;width:100px\">{empid}</li>\r\n              </ul>\r\n            </li>\r\n            <li>\r\n              <ul style=\"display:flex;\">\r\n                <li style=\"width:100px;\">D.O.B</li>\r\n                <li>:</li>\r\n                <li style=\"padding-left:20px;width:100px\">{dob}</li>\r\n              </ul>\r\n            </li>\r\n            <li>\r\n              <ul style=\"display:flex;\">\r\n                <li style=\"width:100px;\">Phone No.</li>\r\n                <li>:</li>\r\n                <li style=\"padding-left:20px;width:100px\">{sms_mobile}</li>\r\n              </ul>\r\n            </li>\r\n            <li>\r\n              <ul style=\"display:flex;\">\r\n                <li style=\"min-width:100px;\">Department</li>\r\n                <li>:</li>\r\n                <li style=\"padding-left:20px;width:100px\">PGT</li>\r\n              </ul>\r\n            </li>\r\n          </ul>\r\n        </li>\r\n      </ul>\r\n    </div>\r\n  </div>\r\n  \r\n  <div style=\"background:url(../images/footer_img_2.png) no-repeat center center; background-size:cover; position:absolute; bottom:0px; width:512px; display:flex; justify-content:space-between; left:0px; border-radius:0px 0px 10px 10px; padding:0px 10px; margin-bottom:0px;\">\r\n<p style=\"text-align:center; padding:30px 0px 10px 0px; color:#fff; font-size:12px;  margin-bottom:0px;\">{website}</p>\r\n<p style=\"text-align:center; padding:30px 0px 10px 0px; co