INSERT INTO `st_paymentterms` VALUES (1,'<b>Without E-Way Bill, we will not accept the material.</b>','Y','2023-09-21 10:16:20'),(2,'<b>Note : 1% LD will be charged per week if material is not dispatched according to the schedule.\n</b><br>\nTest Report of the goods must accompany Consignment.','Y','2023-09-21 10:25:03'),(5,'Price : The Price Mentioned above shall remain firm till full execution of order.','Y','2023-09-21 09:25:05'),(6,'Discount    : Please allow us.......NA.......discount on with above prices.\r\n','Y','2023-09-21 09:27:41'),(7,'GST : Inclusive / Exclusive<br>We need Transport / Duplicate Copy of Challan-cum-invoice TAX Document with the material / Bank<br>Document to enable us to take credit of MODVAT for CED paid by you.<br>It is therefore requested that Material should be dispatched directly by Excise Godown.<br>Please note that Materials may not be accepted by us in the absence of such documents.<br>Please confirm the above prior to dispatch.\r\n ','Y','2023-09-21 09:35:54');
